import React, { useState, useEffect } from "react";

const links = ["About", "Skills", "Projects", "Education", "Contact"];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [active, setActive] = useState("");
  const [theme, setTheme] = useState("dark");

  useEffect(() => {
    const savedTheme =
      localStorage.getItem("theme") || "dark";

    setTheme(savedTheme);

    document.documentElement.setAttribute(
      "data-theme",
      savedTheme
    );

    const onScroll = () =>
      setScrolled(window.scrollY > 40);

    window.addEventListener("scroll", onScroll);

    return () =>
      window.removeEventListener("scroll", onScroll);
  }, []);

  const toggleTheme = () => {
    const newTheme =
      theme === "dark" ? "light" : "dark";

    setTheme(newTheme);

    document.documentElement.setAttribute(
      "data-theme",
      newTheme
    );

    localStorage.setItem("theme", newTheme);
  };

  const scrollTo = (id) => {
    document
      .getElementById(id.toLowerCase())
      ?.scrollIntoView({
        behavior: "smooth",
      });

    setActive(id);
  };

  return (
    <nav
      className="navb"
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 1000,
        padding: "0 32px",
        height: 64,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: scrolled
          ? "rgba(8,11,16,0.92)"
          : "transparent",
        backdropFilter: scrolled
          ? "blur(20px)"
          : "none",
        borderBottom: scrolled
          ? "1px solid rgba(255,255,255,0.06)"
          : "none",
        transition: "all 0.3s ease",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "1200px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        {/* Logo */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
          }}
        >
          <div
            style={{
              width: 36,
              height: 36,
              background:
                "linear-gradient(135deg,#00d4aa,#00a882)",
              borderRadius: 10,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontWeight: 800,
              color: "#080b10",
            }}
          >
            GS
          </div>

          <span
            style={{
              fontWeight: 700,
              fontSize: "1rem",
              color: "var(--text)",
            }}
          >
            Gurpreet Singh
          </span>
        </div>

        {/* Links */}
        <div
          className="nav-desktop"
          style={{
            display: "flex",
            gap: 4,
          }}
        >
          {links.map((l) => (
            <button
              key={l}
              onClick={() => scrollTo(l)}
              style={{
                background:
                  active === l
                    ? "rgba(0,212,170,0.1)"
                    : "transparent",
                border: "none",
                color:
                  active === l
                    ? "#00d4aa"
                    : "var(--muted2)",
                padding: "6px 16px",
                borderRadius: 8,
                cursor: "pointer",
              }}
            >
              {l}
            </button>
          ))}
        </div>

        {/* Right Side */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            style={{
              width: 42,
              height: 42,
              borderRadius: 12,
              border:
                "1px solid var(--border2)",
              background:
                "var(--surface)",
              cursor: "pointer",
              fontSize: "18px",
              color: "var(--text)",
              transition: "0.3s",
            }}
          >
            {theme === "dark" ? "☀️" : "🌙"}
          </button>

          {/* Hire Me */}
          <a
            href="mailto:gurpreetchahal1009@gmail.com"
            style={{
              background:
                "linear-gradient(135deg,#00d4aa,#00a882)",
              color: "#080b10",
              fontWeight: 700,
              fontSize: "0.82rem",
              padding: "8px 20px",
              borderRadius: 10,
              textDecoration: "none",
              boxShadow:
                "0 4px 14px rgba(0,212,170,0.3)",
            }}
          >
            Hire Me →
          </a>
        </div>
      </div>
    </nav>
  );
}
